t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]

def transform(g):
    g=[r[:] for r in g]; H=len(g); W=len(g[0]); mx=max(max(r) for r in g)
    # fill row 0 zero runs by cycle continuation
    r0=g[0]; c=0
    while c<W:
        if r0[c]==0:
            s=c
            while c<W and r0[c]==0: c+=1
            e=c
            if s>0:
                v=r0[s-1]
                for j in range(s,e): v=v%mx+1; r0[j]=v
            else:
                v=r0[e] if e<W else mx
                for j in range(e-1,s-1,-1): v=(v-2)%mx+1; r0[j]=v
        else: c+=1
    # row r (r>=1): cell(c) = row0[c+1] if c<r else row0[c], only where zero
    for r in range(1,H):
        for c in range(W):
            if g[r][c]==0:
                g[r][c]=r0[c+1] if c<r else r0[c]
    return g

